import { BrowserRouter, Routes, Route, NavLink } from 'react-router-dom';
import { Leaf, Clock, Moon, Sun } from 'lucide-react';
import { useState, useEffect } from 'react';
import Recommend from './pages/Recommend';
import BestTime from './pages/BestTime';

// Add global CSS in your index.css or App.css file:
// .dark input, .dark select, .dark textarea { @apply bg-gray-700 text-white border-gray-600; }
// .dark input::placeholder { @apply text-gray-400; }
// .light input, .light select, .light textarea { @apply bg-white text-gray-900 border-gray-300; }

function App() {
  // Theme state management
  const [isDarkMode, setIsDarkMode] = useState(() => {
    const savedTheme = localStorage.getItem('theme');
    // Check saved preference or use system preference as default
    return savedTheme ? savedTheme === 'dark' : window.matchMedia('(prefers-color-scheme: dark)').matches;
  });

  // Update the DOM and localStorage when theme changes
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      document.documentElement.classList.remove('light');
    } else {
      document.documentElement.classList.add('light');
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  // Toggle theme function
  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  return (
    <BrowserRouter>
      <div className={`min-h-screen ${isDarkMode ? 'bg-gray-900 text-gray-100' : 'bg-gray-50 text-gray-800'} transition-colors duration-200`}>
        <nav className={`${isDarkMode ? 'bg-green-800' : 'bg-green-600'} text-white p-4 flex justify-between items-center transition-colors duration-200`}>
          <h1 className="text-xl font-bold flex items-center">
            <Leaf className="mr-2" size={20} />
            🌿 PlantSmart
          </h1>
          <div className="flex items-center space-x-4">
            <NavLink 
              to="/" 
              className={({ isActive }) => 
                `hover:text-green-200 transition-colors ${isActive ? 'font-bold underline' : ''}`
              }
            >
              Recommend Crop
            </NavLink>
            <NavLink 
              to="/best-time" 
              className={({ isActive }) => 
                `hover:text-green-200 transition-colors ${isActive ? 'font-bold underline' : ''}`
              }
            >
              Best Time
            </NavLink>
            <button 
              onClick={toggleTheme}
              className={`p-1 rounded-full transition-colors
                ${isDarkMode 
                  ? 'bg-green-900 text-yellow-200 hover:bg-green-950' 
                  : 'bg-green-700 text-yellow-100 hover:bg-green-800'}`}
              aria-label={isDarkMode ? "Switch to light mode" : "Switch to dark mode"}
              title={isDarkMode ? "Switch to light mode" : "Switch to dark mode"}
            >
              {isDarkMode ? <Sun size={16} /> : <Moon size={16} />}
            </button>
          </div>
        </nav>

        <main className="container mx-auto px-4 py-8">
          <Routes>
            <Route path="/" element={<Recommend isDarkMode={isDarkMode} />} />
            <Route path="/best-time" element={<BestTime isDarkMode={isDarkMode} />} />
          </Routes>
        </main>

        <footer className={`${isDarkMode ? 'bg-green-800' : 'bg-green-600'} text-white p-4 text-center transition-colors duration-200`}>
          <div className="container mx-auto">
            © {new Date().getFullYear()} PlantSmart - Smart agricultural solutions
          </div>
        </footer>
      </div>
    </BrowserRouter>
  );
}

export default App;
